/*! DataTables 1.13.6 */
(function(factory){if(typeof define==="function"&&define.amd){define(["jquery"],function($){return factory($,window,document);});}
else if(typeof exports==="object"){module.exports=function(root,$){if(!root){root=window;}if(!$){$=require("jquery")(root);}
return factory($,root,root.document);};}
else{factory(jQuery,window,document);}}
(function($,window,document,undefined){
"use strict";
var DataTable=function(selector,options){
this.table=$(selector);
this.options=$.extend({
paging:true,
searching:true,
ordering:true,
pageLength:10
},options);
this.init();
};
DataTable.prototype.init=function(){
var self=this;
var rows=this.table.find("tbody tr");
if(this.options.searching){
var input=$('<input type="search" placeholder="Search..." style="margin-bottom:10px;">');
this.table.before(input);
input.on("keyup",function(){
var val=$(this).val().toLowerCase();
rows.each(function(){
$(this).toggle($(this).text().toLowerCase().indexOf(val)>-1);
});
});
}
};
$.fn.DataTable=function(options){
return this.each(function(){
if(!$.data(this,"DataTable")){
$.data(this,"DataTable",new DataTable(this,options));
}
});
};
}));
